  while (n > 0) {
    int charValue = findCharValue(k, n);
    str.append((char)(96 + charValue));
    k -= charValue;
    n--;
  }
  return str.toString();
}

private int findCharValue(int k, int n) {
  int charValue = k / n;
  if (k % n == 0) {
    charValue -= 1;
  }
  return charValue;
}

