public static int longestLine(int[][] mat) {
    // Initialize the maximum length of a line
    int maxLength = 0;

    // Iterate through each row of the matrix
    for (int i = 0; i < mat.length; i++) {
        // Initialize the current length of a line
        int currLength = 0;

        // Iterate through each column of the matrix
        for (int j = 0; j < mat[i].length; j++) {
            // Check if the current cell is 1
            if (mat[i][j] == 1) {
                // Add 1 to the current length of the line
                currLength++;

                // Check if the current length of the line is greater than the maximum length
                if (currLength > maxLength) {
                    // Update the maximum length of the line
                    maxLength = currLength;
                }
            } else {
                // Reset the current length of the line
                currLength = 0;
            }
        }
    }

    // Return the maximum length of a line in the matrix
    return maxLength;
}

